public class Main {
    static class StokHabisException extends RuntimeException {
        StokHabisException(String barang, int sisa) {
            super(barang + " hanya tersisa " + sisa);
        }
    }

    static void ambil(Map<String, Integer> stok, String barang, int jumlah) {
        int sisa = stok.get(barang);
        if (jumlah > sisa) {
            throw new StokHabisException(barang, sisa);
        }
        stok.put(barang, sisa - jumlah);
        System.out.println("Ambil " + jumlah + " " + barang + ", sisa " + (sisa - jumlah));
    }

    public static void main(String[] args) {
        Map<String, Integer> stok = new HashMap<>();
        stok.put("beras 5 kg", 3);
        try {
            ambil(stok, "beras 5 kg", 2);
            ambil(stok, "beras 5 kg", 4);
        } catch (StokHabisException e) {
            System.out.println("Pesanan ditolak: " + e.getMessage());
        }
    }
}

